// Offline: the published website registers a service worker (sw.js, generated by tools/web.mjs), which keeps the whole
// app in the browser, so an installed Rusalka opens without the internet too. The dev server has no sw.js; there the
// registration quietly does nothing.

/** registers sw.js; null without service worker support or where there is no sw.js */
export async function zapnoutOffline({ serviceWorker }) {
  if (!serviceWorker) return null;
  try { return await serviceWorker.register('sw.js', { scope: './' }); }
  catch { return null; }
}
